INSERT INTO `genres` (`id`, `genre_name`, `slug`, `description`) VALUES
(1, 'Vanilla', 'vanilla', 'Truyện tình cảm nhẹ nhàng, ngọt ngào, đôi bên tự nguyện, tôn trọng và yêu thương nhau.'),
(2, 'Romance', 'romance', 'Thể loại tập trung sâu vào yếu tố tình yêu.'),
(3, 'First Love', 'first-love', 'Nội dung khai thác về mối tình đầu.'),
(4, 'Pure Love', 'pure-love', 'Tình yêu thuần khiết, trong sáng, không có yếu tố ép buộc hay cưỡng bức.'),
(5, 'Sweet Couple', 'sweet-couple', 'Câu chuyện về các cặp đôi có mối quan hệ ngọt ngào, lãng mạn.'),
(6, 'Married Couple', 'married-couple', 'Thể loại xoay quanh cuộc sống của các cặp vợ chồng.'),
(7, 'Newlywed', 'newlywed', 'Câu chuyện của những cặp vợ chồng mới cưới.'),
(8, 'Childhood Friend', 'childhood-friend', 'Bạn thanh mai trúc mã, chơi thân với nhau từ nhỏ.'),
(9, 'Senpai', 'senpai', 'Đàn anh'),
(10, 'Kouhai', 'kouhai', 'Đàn em'),
(11, 'Teacher x Student', 'teacher-x-student', 'Mối quan hệ giữa giáo viên và học sinh (thường chỉ dùng cho nhân vật trưởng thành trong tác phẩm người lớn).'),
(12, 'Boss x Employee', 'boss-x-employee', 'Mối quan hệ công sở giữa sếp và nhân viên.'),
(13, 'Office Romance', 'office-romance', 'Tình yêu và những mối quan hệ lén lút chốn công sở.'),
(14, 'Idol Romance', 'idol-romance', 'Chuyện tình cảm hoặc mối quan hệ với thần tượng.'),
(15, 'Celebrity Romance', 'celebrity-romance', 'Chuyện tình cảm với người nổi tiếng.'),
(16, 'Harem', 'harem', 'Một nam chính được vây quanh và có quan hệ với nhiều nhân vật nữ.'),
(17, 'Reverse Harem', 'reverse-harem', 'Một nữ chính được vây quanh và có quan hệ với nhiều nhân vật nam.'),
(18, 'Love Triangle', 'love-triangle', 'Tam giác tình yêu, mối tình tay ba đầy rắc rối và ghen tuông.'),
(19, 'Unrequited Love', 'unrequited-love', 'Yêu đơn phương, tình cảm từ một phía.'),
(20, 'Reconciliation', 'reconciliation', 'Gặp lại và tái hợp sau một thời gian chia tay.'),
(21, 'Long Distance Relationship', 'long-distance-relationship', 'Yêu xa, mối quan hệ bị cản trở bởi khoảng cách địa lý.'),
