(516, 'Oyakodon', 'oyakodon', 'Quan hệ với cả hai mẹ con (hoặc hai bố con) cùng một lúc.'),
(517, 'Siscon', 'siscon', 'Hội chứng cuồng chị gái hoặc em gái đến mức biến thái.'),
(518, 'Brocon', 'brocon', 'Hội chứng cuồng anh trai hoặc em trai.'),
(519, 'Cuddling', 'cuddling', 'Hành vi hai nhân vật ôm ấp, rúc vào nhau một cách bình yên trên giường hoặc ghế sofa.'),
(520, 'Handholding', 'handholding', 'Nắm tay; trong văn hóa doujinshi, đây là hành vi cực kỳ \"bạo dạn\" và lãng mạn của các cặp đôi thuần khiết.'),
(521, 'Sleeping Together', 'sleeping-together', 'Chỉ đơn giản là ngủ chung một giường mà không làm gì, tập trung vào cảm giác an toàn.'),
(522, 'Housewife', 'housewife', 'Tập trung vào hình tượng người vợ đảm đang, ở nhà làm nội trợ chờ chồng nhưng dễ bị sa ngã.'),
(523, 'Western', 'western', 'Thường là bối cảnh cung điện châu Âu cổ, hoàng gia, quý tộc.'),
(524, 'Misunderstanding', 'misunderstanding', 'Nút thắt cốt truyện đẩy cao trào drama bằng các tình huống trớ trêu, dằn vặt.'),
(525, 'Adult', 'adult', 'Nội dung dành cho người lớn với các tình huống chín chắn.'),
(526, 'Mature', 'mature', 'Tình huống trưởng thành, đào sâu vào tâm lý và mối quan hệ phức tạp.'),
(527, 'Small Breasts', 'small-breasts', 'Ngực nhỏ, tạo nét đáng yêu tinh tế cho nhân vật lép.'),
(528, 'Status Difference', 'status-difference', 'Cốt truyện xoay quanh hai nhân vật có địa vị xã hội, gia thế cách biệt lớn.'),
(529, 'Possessive', 'possessive', 'Kiểu nhân vật có ham muốn kiểm soát, giữ chặt đối phương cho riêng mình.'),
(530, 'Academy', 'academy', 'Bối cảnh diễn ra tại trường học, học viện ma pháp hoặc trường nội trú.'),
(531, 'Possessive Male Lead', 'possessive-male-lead', 'Thao tác gắn tag cụ thể khi tính cách chiếm hữu thuộc về nhân vật nam chính.'),
(532, 'Ecchi', 'ecchi', 'Các phân cảnh quyến rũ, hở hang nhẹ nhàng nhưng chưa thâm nhập sâu.'),
(533, 'Smut', 'smut', 'Truyện tình cảm có đan xen các phân cảnh quan hệ thể xác rất chi tiết.'),
(534, 'Webtoon', 'webtoon', 'Định dạng truyện tranh thiết kế cuộn dọc để đọc trên thiết bị điện tử.'),
(535, 'Story Directed', 'story-directed', 'Tác phẩm chú trọng xây dựng nội dung, diễn biến logic thay vì chỉ có cảnh nhạy cảm.'),
(536, 'Slave', 'slave', 'Nhân vật bị mất quyền tự do hoàn toàn, bị mua bán làm công cụ tình dục.'),
(537, 'Story Arc', 'story-arc', 'Tập hợp các chương truyện giải quyết trọn vẹn một tình huống lớn cụ thể.'),
(538, 'Manhua', 'manhua', 'Định dạng truyện tranh có xuất xứ từ các tác giả Trung Quốc.'),
(539, '3D', '3d', 'Thể loại hoạt hình hoặc hình ảnh kích dục được dựng bằng đồ họa máy tính 3 chiều.'),
(540, 'Old Man', 'old-man', 'Nhân vật nam lớn tuổi, già nua (thường xuất hiện trong các mô-típ cưỡng đoạt).'),
(541, 'Friends to Lovers', 'friends-to-lovers', 'Mô-típ cốt truyện xoay quanh hai nhân vật vốn là bạn bè thân thiết rồi dần nảy sinh tình yêu.'),
(542, 'Showbiz', 'showbiz', 'Bối cảnh câu chuyện diễn ra trong giới nghệ sĩ, diễn viên, thần tượng và hào quang nghệ thuật.'),
(543, 'Secret Relationship', 'secret-relationship', 'Cốt truyện xoay quanh cặp đôi phải che giấu mối quan hệ yêu đương của mình với xã hội hoặc người xung quanh.'),
(544, 'Condom', 'condom', 'Phân cảnh sử dụng biện pháp bảo vệ khi quan hệ tình dục.'),
(545, 'Mutual Salvation', 'mutual-salvation', 'Cốt truyện xoay quanh hai nhân vật đều có tổn thương tâm lý, cùng dựa vào nhau để vượt qua bóng tối cuộc đời.'),
(546, 'Netorare', 'netorare', 'Thể loại cắm sừng cốt lõi, nhân vật nam chính bị động nhìn người yêu/vợ bị chiếm đoạt.'),
(547, 'Virgin Boy', 'virgin-boy', 'Nhân vật nam chính còn trinh nguyên, chưa từng có kinh nghiệm phòng the.'),
(548, 'Galgame Adapt', 'galgame-adapt', 'Tác phẩm được chuyển thể hoặc lấy bối cảnh từ các tựa game hẹn hò người lớn.'),
(550, 'Monogamy', 'monogamy', 'Cốt truyện tập trung hoàn toàn vào mối quan hệ một đối một, không có sự xuất hiện của yếu tố đa thê hay người thứ ba làm thay đổi tình cảm.'),
(551, 'Regretful Male Lead', 'regretful-male-lead', 'Thể loại truyện có nam chính ban đầu tệ bạc, lạnh lùng nhưng sau đó hối hận và tìm cách bù đắp.'),
(552, 'Novel', 'novel', 'Tác phẩm truyện chữ (tiểu thuyết) hoặc các bộ truyện tranh được chuyển thể từ nguyên tác Webnovel.'),
(553, 'Incomplete', 'incomplete', 'Tác phẩm chưa kết thúc hoàn toàn, vẫn đang trong quá trình sáng tác hoặc cập nhật.'),
(554, 'Big Vagina', 'big-vagina', 'Mô tả đặc điểm cơ quan sinh dục nữ có kích thước lớn hoặc bị giãn rộng.'),
(555, 'Body Modifications', 'body-modifications', 'Thay đổi cấu trúc cơ thể nhân vật bằng phẫu thuật, phép thuật hoặc các công cụ đặc biệt.'),
(556, 'Pregnant', 'pregnant', 'Nhân vật nữ đang trong thai kỳ hoặc bị làm cho mang thai trong câu chuyện.'),
(557, 'System', 'system', 'Mô-típ nhân vật sở hữu một hệ thống ảo như trong trò chơi (giao nhiệm vụ, cộng điểm, tặng quà).'),
(558, 'Animal Girl', 'animal-girl', 'Nhân vật nữ sở hữu các đặc điểm ngoại hình của động vật (như tai cáo, đuôi cáo).'),
(559, 'Sole Female', 'sole-female', 'Phân cảnh hoặc toàn bộ tác phẩm chỉ có duy nhất một nhân vật nữ tham gia vào mối quan hệ tình dục.'),
(560, 'Sole Male', 'sole-male', 'Phân cảnh hoặc toàn bộ tác phẩm chỉ có duy nhất một nhân vật nam tham gia vào mối quan hệ tình dục.'),
(561, 'Contract Relationship', 'contract-relationship', 'Mô-típ hai nhân vật chính đến với nhau hoặc ràng buộc nhau thông qua một bản hợp đồng thỏa thuận kinh tế, gia thế trước khi nảy sinh tình cảm thật.'),
(562, 'Complex Relationship', 'complex-relationship', 'Mối quan hệ giữa các nhân vật đan xen nhiều khúc mắc, hiểu lầm, ràng buộc xã hội hoặc mâu thuẫn nội tâm đan cài.'),
(563, 'Hardcore', 'hardcore', 'Từ viết biến điệu hoặc lỗi chính tả của \"Hardcore\", chỉ các phân cảnh quan hệ tình dục nặng đô, trần trụi và chi tiết.'),
(564, 'Overpowered Entity', 'overpowered-entity', 'Nhân vật sở hữu sức mạnh, quyền năng tối cao hoặc vị thế vượt xa người thường.'),
(565, 'Scheming Character', 'scheming-character', 'Nhân vật có tính cách thâm trầm, sắc sảo, thích lên kế hoạch và sắp đặt mọi việc theo ý mình.'),
(566, 'Romantic Fantasy', 'romantic-fantasy', 'Thể loại kết hợp giữa yếu tố yêu đương lãng mạn và bối cảnh phép thuật, thế giới giả tưởng.'),
(567, 'Mythology', 'mythology', 'Cốt truyện hoặc bối cảnh lấy cảm hứng từ các vị thần và các điển tích thần thoại.'),
(568, 'Angst', 'angst', 'Thể loại cốt truyện có nội dung đau thương, các nhân vật phải trải qua nhiều dằn vặt, đau đớn về cả thể xác lẫn tinh thần.'),
(569, 'Dirty Talk', 'dirty-talk', 'Hành vi các nhân vật sử dụng những từ ngữ trần trụi, nhạy cảm hoặc kích thích trong lúc quan hệ tình dục.'),
(570, 'Urban', 'urban', 'Bối cảnh câu chuyện diễn ra tại các thành phố lớn, mang phong cách sống hiện đại.'),
(571, 'Fluff', 'fluff', 'Nội dung truyện vô cùng nhẹ nhàng, ấm áp, ngập tràn những khoảnh khắc hạnh phúc và rất ít hoặc không có hiểu lầm, trắc trở.'),
(572, 'CEO', 'ceo', 'Mô-típ nhân vật nam chính là người đứng đầu một tập đoàn lớn, sở hữu tài sản khổng lồ, quyền lực và ngoại hình cuốn hút.'),
(573, 'Censored', 'censored', 'Phiên bản tác phẩm bị áp dụng các biện pháp làm mờ, che vệt trắng hoặc đen lên các bộ phận nhạy cảm theo luật.'),
(574, 'Sweating', 'sweating', 'Chi tiết đặc tả cơ thể nhân vật đẫm mồ hôi do vận động mạnh hoặc do hưng phấn tình dục đẩy lên cao.');
